    constructor(C _c) {
        c = _c;
    }

    function run(address from, address to, uint256 id) public payable {
        require(to != address(0), "to must be nonzero");

        // Drive the contract through a public entry to create a transferable token.
        // The test contract is the only minter via fillOrder; instead, use a direct
        // setup through the public mint path is not available, so use the fact that
        // the checker can run on a fresh c where no token exists yet.
