        bool reverted;
        try c.transferFrom(from, to, id) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: any successful transferFrom must clear the approval for `id`.
        // Since the token may not exist / caller may not be authorized, the call may revert.
        // In the success case, the approval must be zero.
        address approvedAfter = c.getApproved(id);

        assert(reverted || approvedAfter == address(0));
    }

    receive() external payable {}
}

